mapper.select:
SELECT U.USERNAME , U.NAME , U.EMAIL , U.ROLE_CODE , U.DATA_STATUS , U.CREATED_BY , U.CREATED_AT , U.UPDATED_BY , U.UPDATED_AT FROM TB_USER U WHERE TRUE
AND U.USERNAME = #{username}
AND U.ROLE_CODE = #{roleCode}
AND U.DATA_STATUS = #{dataStatus}
ORDER BY U.USERNAME

mapper.insert:
INSERT INTO TB_USER (
    USERNAME
  , NAME
  , EMAIL
  , PASSWORD
  , ROLE_CODE
  , DATA_STATUS
  , CREATED_BY
  , UPDATED_BY
) VALUES (
    #{username}
  , #{name}
  , #{email}
  , #{password}
  , #{roleCode}
  , #{dataStatus}
  , #{author}
  , #{author}
)

mapper.update:
UPDATE TB_USER
   SET UPDATED_BY  = #{author}
     , UPDATED_AT  = NOW()

     , NAME        = #{name}


     , EMAIL       = #{email}


     , DATA_STATUS = #{dataStatus}


     , ROLE_CODE   = #{roleCode}

 WHERE USERNAME    = #{username}

UPDATE TB_USER
   SET PASSWORD            = #{password}


     , PASSWORD_CHANGED_AT = NOW()


     , PASSWORD_CHANGED_AT = NULL


     , UPDATED_BY          = #{author}
     , UPDATED_AT          = NOW()
 WHERE USERNAME            = #{username}

UPDATE TB_USER
   SET PROFILE_IMAGE_FILE_GROUP_ID = #{fileGroupId}
     , UPDATED_BY                  = #{author}
     , UPDATED_AT                  = NOW()
 WHERE USERNAME                    = #{username}
